var params = $input.first().json;

if (!params.template_ref) {
  throw new Error('Missing required field: template_ref');
}
if (!params.user_id) {
  throw new Error('Missing required field: user_id');
}

var uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuidPattern.test(params.user_id)) {
  throw new Error('Invalid user_id format: "' + params.user_id + '". Expected UUID format (e.g. 4a62ed11-6360-41fe-81fb-72f711f23f4b)');
}

var supabaseUrl = params.SUPABASE_URL || 'https://egrzvwnjrtpwwmqzimff.supabase.co';
var bucket = params.SUPABASE_BUCKET || 'panicleDevelop_1';
var fileName = params.template_ref + '_extended_info.xlsx';
var downloadUrl = supabaseUrl + '/storage/v1/object/' + bucket + '/PDF-templates/' + params.template_ref + '/' + fileName;

return [{
  json: {
    template_ref: params.template_ref,
    user_id: params.user_id,
    SUPABASE_URL: supabaseUrl,
    SUPABASE_BUCKET: bucket,
    download_url: downloadUrl,
    original_filename: fileName
  }
}];

var item = $input.first();
var config = $('Validate Params').first().json;

var hasBinary = false;
if (item.binary) {
  var keys = Object.keys(item.binary);
  if (keys.length > 0) { hasBinary = true; }
}

if (!hasBinary) {
  throw new Error('Extended Info Excel not found in Supabase storage. Expected path: PDF-templates/' + config.template_ref + '/' + config.template_ref + '_extended_info.xlsx. Run Add Form Template v0.5 first, then upload the edited file to Supabase.');
}

return [{
  json: {
    template_ref: config.template_ref,
    user_id: config.user_id,
    original_filename: config.original_filename,
    SUPABASE_URL: config.SUPABASE_URL
  },
  binary: item.binary
}];

var rows = $input.all();
var config = $('Check Download Result').first().json;
var newDataKeys = {};
var parseErrors = [];
var rowsParsed = 0;

for (var i = 0; i < rows.length; i++) {
  var row = rows[i].json;
  var pdfField = row['PDF Field Name'] || '';
  var extSource = row['Extended data source'] || '';
  var extValue = row['Extended data value'];

  if (!extSource || String(extSource).trim() === '') {
    continue;
  }
  if (extValue === undefined || extValue === null || String(extValue).trim() === '') {
    continue;
  }

  var trimmedSource = String(extSource).trim();
  var openBracket = trimmedSource.indexOf('[');
  var closeBracket = trimmedSource.indexOf(']');

  if (openBracket === -1 || closeBracket === -1) {
    parseErrors.push('Row ' + (i + 2) + ' (' + pdfField + '): Column D missing [source]. Expected format: data_key [user_details] or [user_details]data_key');
    continue;
  }

  var source = trimmedSource.substring(openBracket + 1, closeBracket).trim();
  var dataKey = '';

  if (openBracket === 0) {
    dataKey = trimmedSource.substring(closeBracket + 1).trim();
  } else {
    dataKey = trimmedSource.substring(0, openBracket).trim();
  }

  if (source.toLowerCase() !== 'user_details') {
    parseErrors.push('Row ' + (i + 2) + ' (' + pdfField + '): Source must be [user_details], got [' + source + ']');
    continue;
  }

  dataKey = dataKey.toLowerCase();

  var validKeyPattern = /^[a-z][a-z0-9_]*$/;
  if (!validKeyPattern.test(dataKey)) {
    parseErrors.push('Row ' + (i + 2) + ' (' + pdfField + '): Invalid data_key "' + dataKey + '". Must be letters, numbers, underscores, starting with a letter.');
    continue;
  }

  newDataKeys[dataKey] = String(extValue).trim();
  rowsParsed++;
}

if (parseErrors.length > 0) {
  throw new Error('Parse errors found:\n' + parseErrors.join('\n'));
}

var keysList = Object.keys(newDataKeys);

if (keysList.length === 0) {
  throw new Error('No data keys found in Excel file. Ensure columns D and E are filled for at least one row.');
}

return [{
  json: {
    template_ref: config.template_ref,
    user_id: config.user_id,
    details_jsonb: newDataKeys,
    keys_list: keysList,
    keys_count: keysList.length,
    SUPABASE_URL: config.SUPABASE_URL
  }
}];

var parsed = $('Parse Excel Rows').first().json;
var rpcResult = $input.first().json;

var keysList = parsed.keys_list || [];
var keysStr = keysList.join(', ');

var msg = 'Successfully updated user_details for user ' + parsed.user_id + '. '
  + 'Added/updated ' + keysList.length + ' data keys: ' + keysStr + '. '
  + 'These values are now available for form filling.';

return [{
  json: {
    status: 'success',
    message: msg,
    user_id: parsed.user_id,
    template_ref: parsed.template_ref,
    keys_updated: keysList,
    keys_count: keysList.length,
    updated_details: rpcResult,
    next_step: 'Run Fill Form workflow with this user_id and any template that has fields mapped to these new data keys.'
  }
}];
